import { RBACManagementPageActivateRoleMutation } from '../__generated__/RBACManagementPageActivateRoleMutation.graphql';
import { RBACManagementPageDeactivateRoleMutation } from '../__generated__/RBACManagementPageDeactivateRoleMutation.graphql';
import { RBACManagementPagePurgeRoleMutation } from '../__generated__/RBACManagementPagePurgeRoleMutation.graphql';
import {
  RBACManagementPageQuery,
  RoleFilter,
  RoleOrderBy,
} from '../__generated__/RBACManagementPageQuery.graphql';
import { RBACManagementPageScopeTypesQuery } from '../__generated__/RBACManagementPageScopeTypesQuery.graphql';
import { App } from '../app-shim';
import RoleDetailDrawerV2 from '../components/RoleDetailDrawerV2';
import RoleFormModal from '../components/RoleFormModal';
import RoleNodes, {
  type RoleNodeInList,
  availableRoleSorterValues,
} from '../components/RoleNodes';
import RolePresetListTab from '../components/RolePresetListTab';
import { convertToOrderBy } from '../helper';
import { rbacTypeI18nKey } from '../helper/rbacElementTypes';
import { useBAIPaginationOptionStateOnSearchParam } from '../hooks/reactPaginationQueryOptions';
import {
  BAIButton,
  BAICard,
  BAIDeleteConfirmModal,
  BAIFetchKeyButton,
  BAIFlex,
  BAIGraphQLPropertyFilter,
  BAINameActionCell,
  BAISelect,
  type BAISelectProps,
  BAISkeleton,
  BAIUnmountAfterClose,
  BAIAdminUserV2Select,
  filterOutEmpty,
  INITIAL_FETCH_KEY,
  useBAILogger,
  useFetchKey,
  useMutationWithPromise,
  BAISegmentedControl,
  BAISegmentedControlItem,
} from 'backend.ai-ui';
import { Trash2, BanIcon, PlusIcon, UndoIcon } from 'lucide-react';
import {
  parseAsJson,
  parseAsString,
  parseAsStringLiteral,
  useQueryStates,
} from 'nuqs';
import { Suspense, useDeferredValue, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { graphql, useLazyLoadQuery, useMutation } from 'react-relay';

const statusFilterValues = ['ACTIVE', 'DELETED'] as const;
const tabValues = ['roles', 'presets'] as const;

// Since 26.9.0 scope types are lowercase names the manager lists, not an enum
// the client could enumerate.
const ScopeTypeSelect: React.FC<Omit<BAISelectProps, 'options'>> = (props) => {
  'use memo';
  const { t } = useTranslation();
  const { rbacScopeEntityCombinations } =
    useLazyLoadQuery<RBACManagementPageScopeTypesQuery>(
      graphql`
        query RBACManagementPageScopeTypesQuery {
          rbacScopeEntityCombinations {
            scopeType
          }
        }
      `,
      {},
      { fetchPolicy: 'store-or-network' },
    );

  return (
    <BAISelect
      showSearch
      label={t('rbac.ScopeType')}
      isLabelHidden
      style={{ width: '100%' }}
      options={(rbacScopeEntityCombinations ?? []).map(({ scopeType }) => ({
        label: t(rbacTypeI18nKey(scopeType), { defaultValue: scopeType }),
        value: scopeType,
      }))}
      {...props}
    />
  );
};

const RoleListTab: React.FC = () => {
  'use memo';

  const { t } = useTranslation();
  const {
    baiPaginationOption,
    tablePaginationOption,
    setTablePaginationOption,
  } = useBAIPaginationOptionStateOnSearchParam({
    current: 1,
    pageSize: 10,
  });

  const [queryParams, setQueryParams] = useQueryStates(
    {
      status: parseAsStringLiteral(statusFilterValues).withDefault('ACTIVE'),
      order: parseAsStringLiteral(availableRoleSorterValues),
      filter: parseAsJson<RoleFilter>((value) => value as RoleFilter),
    },
    {
      history: 'replace',
    },
  );

  const [fetchKey, updateFetchKey] = useFetchKey();

  const queryVariables = {
    filter: {
      status: { in: [queryParams.status] },
      ...queryParams.filter,
    },
    orderBy: convertToOrderBy<RoleOrderBy>(queryParams.order),
    limit: baiPaginationOption.limit,
    offset: baiPaginationOption.offset,
  };

  const deferredQueryVariables = useDeferredValue(queryVariables);
  const deferredFetchKey = useDeferredValue(fetchKey);

  const queryRef = useLazyLoadQuery<RBACManagementPageQuery>(
    graphql`
      query RBACManagementPageQuery(
        $filter: RoleFilter
        $orderBy: [RoleOrderBy!]
        $limit: Int
        $offset: Int
      ) {
        adminRoles(
          filter: $filter
          orderBy: $orderBy
          limit: $limit
          offset: $offset
        ) {
          count
          edges {
            node {
              id
              ...RoleNodesFragment
              ...RoleDetailDrawerV2Fragment
            }
          }
        }
      }
    `,
    deferredQueryVariables,
    {
      fetchPolicy:
        deferredFetchKey === INITIAL_FETCH_KEY
          ? 'store-and-network'
          : 'network-only',
      fetchKey: deferredFetchKey,
    },
  );

  const { message } = App.useApp();
  const { logger } = useBAILogger();

  const [commitDeactivateRole] =
    useMutation<RBACManagementPageDeactivateRoleMutation>(graphql`
      mutation RBACManagementPageDeactivateRoleMutation(
        $input: DeleteRoleInput!
      ) {
        adminDeleteRole(input: $input) {
          id
        }
      }
    `);

  const [commitActivateRole] =
    useMutation<RBACManagementPageActivateRoleMutation>(graphql`
      mutation RBACManagementPageActivateRoleMutation(
        $input: UpdateRoleInput!
      ) {
        adminUpdateRole(input: $input) {
          id
          status
        }
      }
    `);

  const mutatePurgeRole =
    useMutationWithPromise<RBACManagementPagePurgeRoleMutation>(graphql`
      mutation RBACManagementPagePurgeRoleMutation($input: PurgeRoleInput!) {
        adminPurgeRole(input: $input) {
          id
        }
      }
    `);

  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [purgingRole, setPurgingRole] = useState<RoleNodeInList | null>(null);
  const [{ roleDetail: selectedRoleId }, setRoleDetailParam] = useQueryStates(
    {
      roleDetail: parseAsString,
    },
    {
      history: 'push',
    },
  );
  const handleDeactivateRole = (role: RoleNodeInList) => {
    commitDeactivateRole({
      variables: { input: { id: role.entityId } },
      onCompleted: (_data, errors) => {
        if (errors && errors.length > 0) {
          logger.error(errors[0]);
          message.error(errors[0]?.message || t('general.ErrorOccurred'));
          return;
        }
        message.success(t('rbac.RoleDeactivated'));
        updateFetchKey();
      },
      onError: (error) => {
        logger.error(error);
        message.error(error?.message || t('general.ErrorOccurred'));
      },
    });
  };

  const handleActivateRole = (role: RoleNodeInList) => {
    commitActivateRole({
      variables: {
        input: { id: role.entityId, status: 'ACTIVE' },
      },
      onCompleted: (_data, errors) => {
        if (errors && errors.length > 0) {
          logger.error(errors[0]);
          message.error(errors[0]?.message || t('general.ErrorOccurred'));
          return;
        }
        message.success(t('rbac.RoleActivated'));
        updateFetchKey();
      },
      onError: (error) => {
        logger.error(error);
        message.error(error?.message || t('general.ErrorOccurred'));
      },
    });
  };

  const handlePurgeRole = (role: RoleNodeInList) => {
    setPurgingRole(role);
  };

  const roleNodes = queryRef.adminRoles?.edges?.map((edge) => edge?.node) ?? [];
  // The drawer renders from the selected node's fragment ref — no id-based
  // fetch of its own. If the node has drifted off the current page (rare:
  // reload after list churn), the drawer simply stays closed.
  const selectedRole = roleNodes.find((role) => role?.id === selectedRoleId);

  return (
    <>
      <BAIFlex direction="column" align="stretch" gap={'sm'}>
        <BAIFlex justify="between" wrap="wrap" gap={'sm'}>
          <BAIFlex
            gap={'sm'}
            align="start"
            wrap="wrap"
            style={{ flexShrink: 1 }}
          >
            <BAISegmentedControl
              value={queryParams.status}
              onChange={(value) => {
                setQueryParams({ status: value as typeof queryParams.status });
                setTablePaginationOption({ current: 1 });
              }}
            >
              <BAISegmentedControlItem
                value="ACTIVE"
                label={t('rbac.Active')}
              />
              <BAISegmentedControlItem
                value="DELETED"
                label={t('rbac.Inactive')}
              />
            </BAISegmentedControl>
            <BAIGraphQLPropertyFilter<RoleFilter>
              filterProperties={filterOutEmpty([
                {
                  key: 'name',
                  propertyLabel: t('rbac.RoleName'),
                  type: 'string',
                },
                {
                  key: 'source',
                  propertyLabel: t('rbac.Source'),
                  type: 'enum',
                  fixedOperator: 'equals',
                  options: [
                    { label: t('rbac.System'), value: 'SYSTEM' },
                    { label: t('rbac.Custom'), value: 'CUSTOM' },
                  ],
                  strictSelection: true,
                },
                {
                  key: 'assignedUser.userId',
                  propertyLabel: t('rbac.AssignedUser'),
                  type: 'uuid',
                  fixedOperator: 'equals',
                  renderInput: ({ onAddCondition, value, isDisabled }) => (
                    <Suspense fallback={<BAISelect disabled loading />}>
                      <BAIAdminUserV2Select
                        valuePropName="id"
                        value={value}
                        isDisabled={isDisabled}
                        label={t('rbac.AssignedUser')}
                        isLabelHidden
                        onChange={(value, option) =>
                          // The picker emits the user UUID; forward the option
                          // label (email) so the condition tag stays readable
                          // (P3C-1 keeps the 2nd argument on this sibling).
                          onAddCondition(
                            value as string | undefined,
                            Array.isArray(option)
                              ? option[0]?.label
                              : option?.label,
                          )
                        }
                      />
                    </Suspense>
                  ),
                },
                {
                  key: 'mappedScope.scopeType',
                  propertyLabel: t('rbac.ScopeType'),
                  type: 'enum',
                  fixedOperator: 'equals',
                  // The select owns its query and suspends on first open.
                  renderInput: ({ onAddCondition, value, isDisabled }) => (
                    <Suspense
                      fallback={
                        <BAISelect
                          loading
                          disabled
                          label={t('rbac.ScopeType')}
                          isLabelHidden
                          style={{ width: '100%' }}
                        />
                      }
                    >
                      <ScopeTypeSelect
                        value={value}
                        disabled={isDisabled}
                        onChange={(next, option) =>
                          onAddCondition(next, option?.label)
                        }
                      />
                    </Suspense>
                  ),
                },
                {
                  key: 'mappedScope.scopeId',
                  propertyLabel: t('rbac.ScopeRawId'),
                  type: 'uuid',
                  fixedOperator: 'equals',
                },
              ])}
              value={queryParams.filter ?? undefined}
              onChange={(value) => {
                setQueryParams({ filter: value ?? null });
                setTablePaginationOption({ current: 1 });
              }}
            />
          </BAIFlex>
          <BAIFlex gap={'xs'}>
            <BAIFetchKeyButton
              loading={
                deferredQueryVariables !== queryVariables ||
                deferredFetchKey !== fetchKey
              }
              value={fetchKey}
              onChange={(newFetchKey) => {
                updateFetchKey(newFetchKey);
              }}
            />
            <BAIButton
              type="primary"
              icon={<PlusIcon />}
              onClick={() => setIsCreateModalOpen(true)}
            >
              {t('rbac.CreateRole')}
            </BAIButton>
          </BAIFlex>
        </BAIFlex>
        <RoleNodes
          rolesFrgmt={roleNodes}
          loading={deferredQueryVariables !== queryVariables}
          order={queryParams.order}
          onChangeOrder={(order) => {
            setQueryParams({ order });
          }}
          customizeColumns={(columns) => {
            const isDeletedFilter =
              deferredQueryVariables.filter.status?.in?.[0] === 'DELETED';
            return columns.map((col) =>
              col.key === 'name'
                ? {
                    ...col,
                    render: (name: string, role: RoleNodeInList) => (
                      <BAINameActionCell
                        title={name}
                        showActions="always"
                        onTitleClick={() =>
                          setRoleDetailParam({ roleDetail: role.id })
                        }
                        actions={filterOutEmpty(
                          isDeletedFilter
                            ? [
                                {
                                  key: 'activate',
                                  title: t('rbac.Activate'),
                                  icon: <UndoIcon />,
                                  popConfirm: {
                                    title: t('rbac.ActivateRole'),
                                    description: role.name,
                                    okText: t('rbac.Activate'),
                                    cancelText: t('button.Cancel'),
                                    onConfirm: () => {
                                      return new Promise<void>((resolve) => {
                                        handleActivateRole(role);
                                        resolve();
                                      });
                                    },
                                  },
                                },
                                {
                                  key: 'purge',
                                  title: t('rbac.PurgeRole'),
                                  icon: <Trash2 size="1em" />,
                                  type: 'danger' as const,
                                  onClick: () => handlePurgeRole(role),
                                },
                              ]
                            : [
                                {
                                  key: 'deactivate',
                                  title: t('rbac.Deactivate'),
                                  icon: <BanIcon />,
                                  type: 'danger' as const,
                                  popConfirm: {
                                    title: t('rbac.DeactivateRole'),
                                    description: role.name,
                                    okText: t('rbac.Deactivate'),
                                    cancelText: t('button.Cancel'),
                                    okButtonProps: { danger: true },
                                    onConfirm: () => {
                                      return new Promise<void>((resolve) => {
                                        handleDeactivateRole(role);
                                        resolve();
                                      });
                                    },
                                  },
                                },
                              ],
                        )}
                      />
                    ),
                  }
                : col,
            );
          }}
          pagination={{
            pageSize: tablePaginationOption.pageSize,
            current: tablePaginationOption.current,
            total: queryRef.adminRoles?.count ?? 0,
            onChange: (current, pageSize) => {
              setTablePaginationOption({ current, pageSize });
            },
          }}
        />
      </BAIFlex>
      <RoleFormModal
        open={isCreateModalOpen}
        onRequestClose={(success) => {
          setIsCreateModalOpen(false);
          if (success) {
            updateFetchKey();
          }
        }}
      />
      <BAIUnmountAfterClose>
        <RoleDetailDrawerV2
          open={!!selectedRole}
          roleFrgmt={selectedRole}
          onClose={() => setRoleDetailParam({ roleDetail: null })}
        />
      </BAIUnmountAfterClose>
      <BAIDeleteConfirmModal
        open={!!purgingRole}
        items={
          purgingRole
            ? [{ key: purgingRole.id, label: purgingRole.name ?? '' }]
            : []
        }
        title={t('rbac.PurgeRole')}
        target={t('general.Role')}
        confirmText={purgingRole?.name ?? ''}
        requireConfirmInput
        onOk={() => {
          if (purgingRole) {
            return mutatePurgeRole({
              input: { id: purgingRole.entityId },
            })
              .then(() => {
                message.success(t('rbac.RolePurged'));
                updateFetchKey();
                setPurgingRole(null);
              })
              .catch((error) => {
                logger.error('Failed to purge role', error);
                message.error(error?.message || t('general.ErrorOccurred'));
                setPurgingRole(null);
              });
          }
        }}
        onCancel={() => setPurgingRole(null)}
      />
    </>
  );
};

const RBACManagementPage: React.FC = () => {
  'use memo';

  const { t } = useTranslation();
  const [{ tab }, setQueryParams] = useQueryStates(
    {
      tab: parseAsStringLiteral(tabValues).withDefault('roles'),
      // Tab-owned params, cleared on a tab switch so one tab's list state
      // never reaches the other's query.
      status: parseAsString,
      order: parseAsString,
      filter: parseAsString,
      current: parseAsString,
      pageSize: parseAsString,
      roleDetail: parseAsString,
      presetDetail: parseAsString,
    },
    { history: 'push' },
  );
  return (
    <BAICard
      activeTabKey={tab}
      onTabChange={(key) => {
        setQueryParams({
          tab: key as (typeof tabValues)[number],
          status: null,
          order: null,
          filter: null,
          current: null,
          pageSize: null,
          roleDetail: null,
          presetDetail: null,
        });
      }}
      tabList={[
        { key: 'roles', label: t('rbac.Roles') },
        { key: 'presets', label: t('rbac.Presets') },
      ]}
    >
      <Suspense fallback={<BAISkeleton rows={4} />}>
        {tab === 'presets' ? <RolePresetListTab /> : <RoleListTab />}
      </Suspense>
    </BAICard>
  );
};

export default RBACManagementPage;
